# Break My Fix finding 2, generated by Tracefix: slugify returns a wrong value.
# Property (docstring): Words are separated by single dashes, never by runs of dashes.
# Quote: lowercase, dash-separated slug for its URL
# Run it with pytest: it fails for as long as the code breaks this property.

from blog.slug import slugify


def test_break_my_fix_2() -> None:
    title = '[^a-z0-9 -]'
    result = slugify(title='[^a-z0-9 -]')
    assert ('--' not in result)
